        .npc-row {
            display: flex;
            align-items: flex-start;
            margin-bottom: 6px;
        }

        .npc-row:last-child {
            margin-bottom: 0;
        }

        .npc-row-label {
            color: var(--text-sub);
            font-size: calc(var(--base-font-size) - 3px);
            width: 30px;
            flex-shrink: 0;

        }

        .npc-row-val {
            flex: 1;
            font-size: calc(var(--base-font-size) - 2px);
            color: var(--text-main);
            line-height: 1.5;
            min-width: 0;
            /* 修复：允许容器在空间不足时收缩 */
            word-wrap: break-word;
            /* 修复：强制长文本换行 */
            word-break: break-word;
            /* 修复：防止文字溢出屏幕 */
            white-space: pre-wrap;
            /* 修复：保留多行字段的换行符 */
        }


        /* 主动发起 */
        .initiative-section {
            margin-top: 10px;
        }

        .initiative-header {
            display: flex;
            align-items: center;
            gap: 6px;
            margin-bottom: 6px;
            padding: 0 4px;
        }

        .initiative-speaker {
            font-weight: 600;
            font-size: calc(var(--base-font-size) - 2px);
            color: var(--theme-color-1);
        }

        .initiative-tag {
            font-size: calc(var(--base-font-size) - 5px);
            padding: 2px 6px;
            border-radius: 50px;
            background: var(--tag-bg);
            color: var(--theme-color-1);
        }

        .initiative-bubble {
            display: flex;
            flex-direction: column;
            max-width: 88%;
        }

        .initiative-content {
            background: var(--char-color);
            color: var(--text-main);
            padding: 10px 14px;
            border-radius: 18px;
            border-top-left-radius: 4px;
            font-size: calc(var(--base-font-size) - 1px);
            line-height: 1.6;
            white-space: pre-wrap;
            /* 修复：保留多行字段的换行符 */
        }

        /* ========== 生活状态块 ========== */
        .life-block {
            margin-top: 10px;
            display: grid;
            gap: 8px;
            margin-bottom: 12px;
        }

        .life-item {
            background: var(--ui-color-main);
            border: none;
            border-radius: var(--box-border-radius);
            padding: 8px 10px;
        }

        .life-tag {
            font-size: calc(var(--base-font-size) - 2px);
            font-weight: 800;
            background: var(--gradient-main);
            -webkit-background-clip: text;
            background-clip: text;
            color: transparent;
            text-transform: uppercase;
            margin-bottom: 5px;
            letter-spacing: 0.5px;
        }

        .life-val {
            font-size: calc(var(--base-font-size) - 2px);
            color: var(--text-main);
            line-height: 1.5;
        }

        /* ========== 胶囊/铭牌 ========== */
        .capsule-row {
            display: flex;
            flex-wrap: wrap;
            gap: 10px;
            margin-bottom: 10px;
        }

        .capsule-label {
            font-size: calc(var(--base-font-size) - 3px);
            color: var(--text-sub);
            width: 100%;
            margin-bottom: 4px;
            font-weight: bold;
        }

        .person-nameplate {
            display: inline-block;
            background: var(--gradient-main);
            border: none;
            color: var(--text-on-gradient);
            padding: 3px 12px;
            border-radius: 50px;
            font-size: calc(var(--base-font-size) - 3px);
            font-weight: bold;
            transition: all 0.2s;
            cursor: pointer;
            user-select: none;
        }

        .person-nameplate:hover {
            transform: translateY(-1px);
            box-shadow: 0 0 5px 1px var(--hover-glow);
        }



        /* ========== 场景项 ========== */

        .scene-item {
            display: flex;
            margin-bottom: 5px;
            font-size: calc(var(--base-font-size) - 1px);
            align-items: baseline;
        }

        .scene-key {
            color: var(--text-sub);
            width: 40px;
            flex-shrink: 0;
            font-size: calc(var(--base-font-size) - 2px);
            opacity: 0.7;
        }

        .scene-val {
            color: var(--text-main);
            flex: 1;
        }

        /* ========== 用户气泡 ========== */
        .user-bubble {
            position: relative;
            background: var(--user-color);
            border: none;
            border-radius: var(--box-border-radius);
            padding: 15px 18px;
            color: var(--text-main);
            font-size: var(--base-font-size);
            line-height: 1.6;
            max-width: 95%;
            margin-bottom: 10px;
            box-shadow: 0 0 0 2px color-mix(in srgb, var(--theme-color-2) 60%, transparent),
                0 0 10px 2px color-mix(in srgb, var(--theme-color-1) 60%, transparent);
        }

        /* ========== 记忆列表 ========== */
        .mem-list-clean {
            display: flex;
            flex-direction: column;
            gap: 10px;
            margin-top: 5px;
        }

        .mem-item-clean {
            background: var(--ui-color-sec);
            border: none;
            border-radius: var(--box-border-radius);
            overflow: hidden;
            transition: all 0.2s;
        }

        .mem-item-clean:hover {
            background: var(--highlight-bg);
        }

        .mem-header-clean {
            padding: 8px 12px;
            display: flex;
            align-items: center;
            gap: 12px;
            cursor: pointer;
            user-select: none;
        }

        .mem-id-tag {
            background: var(--gradient-main);
            color: var(--text-on-gradient);
            padding: 3px 8px;
            border-radius: var(--border-radius-small);
            font-size: calc(var(--base-font-size) - 3px);
            font-weight: bold;
        }

        .mem-title-clean {
            flex: 1;
            font-size: calc(var(--base-font-size) - 1px);
            color: var(--text-sub);
            opacity: 0.8;
            text-align: right;
        }

        .mem-toggle-icon {
            font-size: 10px;
            background: var(--gradient-main);
            -webkit-background-clip: text;
            background-clip: text;
            color: transparent;
            transition: transform 0.3s;
        }

        .mem-body-clean {
            padding: 10px;
            font-size: calc(var(--base-font-size) - 1px);
            color: var(--text-main);
            border-top: none;
            background: var(--ui-color-main);
            line-height: 1.7;
            display: none;
            animation: slideDown 0.2s;
            border-radius: 0 0 var(--box-border-radius) var(--box-border-radius);
        }

        .mem-item-clean.expanded .mem-body-clean {
            display: block;
        }

        .loading-tip {
            font-size: calc(var(--base-font-size) - 2px);
            color: var(--text-sub);
            font-style: italic;
            opacity: 0.7;
            text-align: center;
            display: block;
            padding: 20px 0;
        }

        .sub-note {
            font-size: calc(var(--base-font-size) - 3px);
            opacity: 0.6;
            display: block;
            margin-top: 8px;
        }

        /* ========== 剧情阅读器 ========== */
        .plot-details-wrapper {
            display: flex;
            flex-direction: column;
            gap: 12px;
        }



        .plot-reader-panel {
            margin-top: 12px;
            background: var(--ui-color-main);
            border: none;
            border-radius: var(--box-border-radius);
            padding: 10px;
            display: none;
            animation: slideDown 0.3s ease-out;
            overflow: hidden;
        }

        .plot-reader-panel.show {
            display: block;
        }

        .plot-reader-header {
            display: flex;
            align-items: center;
            gap: 10px;
            padding: 0 0 8px 0;
            background: transparent;
            border-bottom: none;
        }

        .plot-reader-id {
            font-weight: bold;
            background: var(--gradient-main);
            -webkit-background-clip: text;
            background-clip: text;
            color: transparent;
            font-size: var(--base-font-size);
        }

        .plot-reader-id::before {
            content: "✦ ";
            background: var(--gradient-main);
            -webkit-background-clip: text;
            background-clip: text;
            color: transparent;
            font-size: calc(var(--base-font-size) * 1.1);
        }

        .plot-reader-content {
            padding: 0;
        }

        .plot-meta-container {
            display: flex;
            gap: 15px;
            flex-wrap: wrap;
            padding-bottom: 8px;
            margin-bottom: 8px;
            border-bottom: none;
        }

        .plot-meta-item {
            display: flex;
            align-items: center;
            gap: 8px;
            font-size: calc(var(--base-font-size) - 2px);
            color: var(--text-sub);
        }

        .plot-meta-item svg {
            width: 14px;
            height: 14px;
            fill: var(--theme-color-1);
            opacity: 0.7;
        }

        .plot-detail-card {
            background: var(--sub-card-bg);
            border-radius: var(--box-border-radius);
            padding: 15px;
        }

        .plot-section-title {
            display: flex;
            align-items: center;
            gap: 8px;
            font-size: calc(var(--base-font-size) - 2px);
            font-weight: bold;
            color: var(--text-main);
            text-transform: uppercase;
            letter-spacing: 1px;
            margin-bottom: 12px;
        }

        .plot-section-title::before {
            content: "✦";
            background: var(--gradient-main);
            -webkit-background-clip: text;
            background-clip: text;
            color: transparent;
            font-size: calc(var(--base-font-size) * 1.1);
        }

        .plot-section-title svg {
            display: none;
        }

        .plot-summary-content {
            line-height: 1.8;
            color: var(--text-main);
            font-size: calc(var(--base-font-size) - 1px);
            text-align: justify;
        }

        /* ========== 对话气泡 ========== */
        .plot-dialogue-list {
            display: flex;
            flex-direction: column;
            gap: 12px;
        }

        .dialogue-bubble {
            display: flex;
            flex-direction: column;
            max-width: 75%;
        }

        .dialogue-bubble.speaker-left {
            align-self: flex-start;
        }

        .dialogue-bubble.speaker-right {
            align-self: flex-end;
        }

        .dialogue-speaker {
            font-weight: 600;
            font-size: calc(var(--base-font-size) - 2px);
            margin-bottom: 4px;
            padding: 0 4px;
        }

        .dialogue-bubble.speaker-left .dialogue-speaker {
            color: var(--text-sub);
        }

        .dialogue-bubble.speaker-right .dialogue-speaker {
            color: var(--theme-color-1);
            text-align: right;
        }

        .dialogue-content {
            padding: 10px 14px;
            border-radius: 18px;
            line-height: 1.6;
            font-size: calc(var(--base-font-size) - 1px);
            position: relative;
        }

        .dialogue-bubble.speaker-left .dialogue-content {
            background: var(--char-color);
            color: var(--text-main);
            border-top-left-radius: 4px;
        }

        .dialogue-bubble.speaker-right .dialogue-content {
            background: var(--gradient-main);
            color: var(--text-on-gradient);
            border-top-right-radius: 4px;
        }

        /* ========== NPC选择器 & 互动区 ========== */
        .npc-selector {
            display: flex;
            flex-wrap: wrap;
            gap: 10px;
            padding-bottom: 15px;
        }

        .npc-selector .person-nameplate {
            cursor: pointer;
            opacity: 1;
        }

        .npc-selector .person-nameplate.no-detail {
            opacity: 0.5;
            background: var(--sub-card-bg);
        }

        .npc-selector .person-nameplate.no-detail:hover {
            opacity: 0.8;
        }

        .npc-selector .person-nameplate:not(.no-detail):hover,
        .npc-selector .person-nameplate.active {
            opacity: 1;
            transform: translateY(-1px);
            box-shadow: 0 0 5px 1px var(--hover-glow);
        }

        .npc-card-wrapper {
            display: none;
            margin-bottom: 15px;
        }

        .npc-card-wrapper.active {
            display: block;
            animation: fadeIn 0.3s ease-in-out;

        }

        @keyframes fadeIn {
            from {
                opacity: 0;
                transform: translateY(5px);
            }

            to {
                opacity: 1;
                transform: translateY(0);
            }
        }


        /* ========== 时空乐章 - 章节状态 ========== */

        .chapter-header-box {
            display: flex;
            justify-content: space-between;
            align-items: flex-start;
            margin-bottom: 12px;
            padding-bottom: 10px;
            border-bottom: none;
            gap: 10px;
        }

        .chapter-name {
            font-size: calc(var(--base-font-size) + 2px);
            font-weight: bold;
            background: linear-gradient(90deg, var(--theme-color-1), var(--theme-color-2));
            -webkit-background-clip: text;
            background-clip: text;
            color: transparent;
            word-break: break-word;
            line-height: 1.5;
            flex: 1;
            min-width: 0;
        }



        .chapter-tags-row {
            display: flex;
            flex-wrap: wrap;
            justify-content: flex-end;
            gap: 6px;
            align-items: center;
            flex-shrink: 1;
            margin-left: auto;
        }

        .chapter-tag {
            padding: 3px 10px;
            border-radius: 50px;
            font-size: calc(var(--base-font-size) - 3px);
            font-weight: bold;
            /* ✓ 已加粗 */
            background: var(--tag-bg);
            color: var(--theme-color-1);
            border: none;
            flex-shrink: 0;
            white-space: nowrap;
            text-align: center;
            box-sizing: border-box;
        }

        .chapter-tag[data-type="timeskip"] {
            background: var(--urgency-leisure-bg);
            color: var(--urgency-leisure-text);
        }

        /* Default for Type and Difficulty is Normal (Gray) */
        .chapter-tag[data-type="type"],
        .chapter-tag[data-type="difficulty"] {
            background: var(--urgency-normal-bg);
            color: var(--urgency-normal-text);
        }

        /* Type: 冒险(Orange/Urgent), 日常(Blue/Leisure), 混合(Normal/Gray) */
        .chapter-tag[data-type="type"][data-val="冒险"] {
            background: var(--urgency-urgent-bg);
            color: var(--urgency-urgent-text);
        }

        .chapter-tag[data-type="type"][data-val="日常"] {
            background: var(--urgency-leisure-bg);
            color: var(--urgency-leisure-text);
        }

        .chapter-tag[data-type="type"][data-val="混合"] {
            background: var(--urgency-ordinary-bg);
            color: var(--urgency-ordinary-text);
        }

        /* Difficulty: 低、中、高 三级渐进色 (兼容旧版五级词汇和新版) */
        .chapter-tag[data-type="difficulty"][data-val="低"],
        .chapter-tag[data-type="difficulty"][data-val="简单"],
        .chapter-tag[data-type="difficulty"][data-val="轻松"] {
            background: var(--urgency-leisure-bg);
            color: var(--urgency-leisure-text);
        }

        .chapter-tag[data-type="difficulty"][data-val="普通"],
        .chapter-tag[data-type="difficulty"][data-val="一般"] {
            background: var(--urgency-ordinary-bg);
            color: var(--urgency-ordinary-text);
        }

        .chapter-tag[data-type="difficulty"][data-val="中"],
        .chapter-tag[data-type="difficulty"][data-val="困难"] {
            background: var(--urgency-urgent-bg);
            color: var(--urgency-urgent-text);
        }

        .chapter-tag[data-type="difficulty"][data-val="高"],
        .chapter-tag[data-type="difficulty"][data-val="险峻"],
        .chapter-tag[data-type="difficulty"][data-val="危险"] {
            background: var(--urgency-crisis-bg);
            color: var(--urgency-crisis-text);
        }

        .chapter-tag[data-type="difficulty"][data-val="极高"],
        .chapter-tag[data-type="difficulty"][data-val="绝境"] {
            background: var(--urgency-desperate-bg);
            color: var(--urgency-desperate-text);
        }


        /* ========== 修正版：括号与文字同色，底对齐 ========== */
        .obj-weight {
            padding: 0;
            font-size: calc(var(--base-font-size) - 2px);
            margin: 0 4px 0 0;
            flex-shrink: 0;
            background: none !important;
            display: inline-block;
            min-width: auto;
            text-align: left;
            /* 确保行内元素垂直对齐 */
            vertical-align: baseline;
        }

        /* 伪元素只加括号，颜色样式完全继承父元素，不再单独设置灰色 */
        .obj-weight::before {
            content: "[";
        }

        .obj-weight::after {
            content: "]";
        }

        /* [必须] - 整体粉色 */
        .obj-weight[data-weight="必须"],
        .obj-weight[data-weight="主线"] {
            color: var(--theme-color-1);
        }

        /* [可选] - 整体灰色 */
        .obj-weight[data-weight="可选"],
        .obj-weight[data-weight="支线"] {
            color: var(--text-weak);
            font-weight: normal;
            opacity: 0.8;
        }

        /* 状态文字样式：改为纯行内元素，强制文字底对齐 */
        .obj-condition {
            font-size: calc(var(--base-font-size) - 2px);
            color: var(--text-sub);
            opacity: 0.8;
            /* 关键：去掉 flex，改为 inline，让文字自然落在基线上 */
            display: inline;
            margin-left: 4px;
        }

        .appointment-deadline {
            padding: 2px 8px;
            border-radius: 50px;
            font-size: calc(var(--base-font-size) - 4px);
            font-weight: bold;
            /* 修正：去除硬编码，使用变量 */
            background: var(--urgency-normal-bg);
            color: var(--text-sub);
            flex-shrink: 0;
            margin-left: auto;
            min-width: 40px;
            text-align: center;
        }

        .objectives-box {
            background: var(--ui-color-main);
            border-radius: var(--box-border-radius);
            padding: 12px;
            margin: 10px 0;
        }

        .objectives-label {
            font-size: calc(var(--base-font-size) - 3px);
            font-weight: bold;
            background: var(--gradient-main);
            -webkit-background-clip: text;
            background-clip: text;
            color: transparent;
            margin-bottom: 10px;
            text-transform: uppercase;
            letter-spacing: 1px;
        }

        .objectives-label::before {
            content: "✦ ";
        }

        /* ========== 场景信息盒子 ========== */
        .scene-meta-box {
            display: flex;
            flex-direction: column;
            gap: 8px;
            margin-bottom: 12px;
        }

        .scene-meta-box .objectives-label {
            margin-bottom: 0;
        }

        /* ========== 任务列表 - 字符图标模式 ========== */
        .objectives-list {
            display: flex;
            flex-direction: column;
            gap: 2px;
        }

        .obj-item {
            display: flex;
            align-items: baseline;
            gap: 8px;
            padding: 1px 0;
        }


        .obj-icon {
            font-size: calc(var(--base-font-size) - 2px);
            width: 14px;
            text-align: center;
            flex-shrink: 0;
            transition: all 0.3s ease;
        }


        .obj-content {
            flex: 1;
            display: flex;
            flex-direction: column;
            gap: 4px;
        }

        .obj-text {
            font-size: calc(var(--base-font-size) - 1px);
            color: var(--text-main);
            transition: opacity 0.3s;
        }

        .obj-condition {
            font-size: calc(var(--base-font-size) - 3px);
            color: var(--text-weak);
            opacity: 0.8;
            display: inline;
            gap: 4px;
        }

        .obj-cond-arrow {
            color: var(--theme-color-1);
            font-size: calc(var(--base-font-size) - 4px);
        }

        /* 未触发状态 - ✧ 空心灰色 */
        .obj-item.obj-pending .obj-icon {
            color: var(--text-sub);
            opacity: 1;
        }

        .obj-item.obj-pending .obj-text {
            opacity: 1;
            color: var(--text-main);
        }

        /* 进行中状态 - ◈ 渐变发光 */
        .obj-item.obj-active .obj-icon {
            background: var(--gradient-main);
            -webkit-background-clip: text;
            background-clip: text;
            color: transparent;
            /* 修正：使用变量 + color-mix 替代硬编码 RGB */
            filter:
                drop-shadow(0 0 1px color-mix(in srgb, var(--theme-color-1) 40%, transparent)) drop-shadow(0 0 2px color-mix(in srgb, var(--theme-color-1) 30%, transparent));
            animation: icon-pulse 2.5s ease-in-out infinite;
        }

        .obj-item.obj-active .obj-text {
            color: var(--text-main);
            opacity: 1;
        }



        /* 发光脉冲动画 */
        @keyframes icon-pulse {

            0%,
            100% {
                filter: drop-shadow(0 0 4px var(--theme-color-1));
                opacity: 0.7;
            }

            50% {
                filter: drop-shadow(0 0 8px var(--theme-color-1));
                opacity: 1;
            }
        }



        .antagonist-box {
            background: var(--ui-color-main);
            border: none;
            border-radius: var(--box-border-radius);
            padding: 12px 15px;
            margin-top: 10px;
        }

        .antagonist-label {
            display: inline-block;
            font-size: calc(var(--base-font-size) - 3px);
            font-weight: bold;
            background: var(--gradient-main);
            -webkit-background-clip: text;
            background-clip: text;
            color: transparent;
            margin-bottom: 10px;
            text-transform: uppercase;
            letter-spacing: 1px;
        }

        .antagonist-label::before {
            content: "✦ ";
        }

        .antagonist-val {
            font-size: calc(var(--base-font-size) - 1px);
            color: var(--text-main);
            line-height: 1.6;
            opacity: 0.9;
        }



        /* ========== 约定项样式 ========== */
        .promise-list {
            display: flex;
            flex-direction: column;
            gap: 2px;
        }

        .affordance-box {
            background: var(--ui-color-main);
            border-radius: var(--box-border-radius);
            padding: 12px;
            margin: 10px 0;
        }

        .promise-item {
            display: flex;
            align-items: baseline;
            gap: 8px;
            padding: 1px 0;
        }



        .promise-content {
            flex: 1;
            font-size: calc(var(--base-font-size) - 1px);
            color: var(--text-main);
            line-height: 1.5;
        }



        /* ========== 视界之外 - 浅灰风格 ========== */
        .section.offstage-section .sec-header {
            background: transparent;
        }

        .section.offstage-section .sec-title {
            background: none;
            -webkit-background-clip: unset;
            background-clip: unset;
            color: var(--text-sub);
