            margin-bottom: 10px;
        }

        /* 念念不忘高亮标签 */
        .hl-statement {
            color: var(--theme-color-1);
        }
    </style>
</head>

<body>
    <textarea id="time-capsule">$1</textarea>
    <div id="planner-app" class="planner-card">
        <div class="header-bar" onclick="toggleCard()">
            <div class="chrono-header" id="chrono-header">
                <!-- 由JS动态填充 -->
            </div>
            <div class="control-grp">
                <div class="toggle-arrow">✧</div>
            </div>
        </div>
        <div class="content-body" id="render-area">
            <div style="text-align:center;color:var(--text-sub);padding:20px;">✦ 正在聆听回响...</div>
        </div>
    </div>

    <script>
        // ===== 当前文本解析工具 =====

        const USER_DEFAULT_CONFIG = { "openMain": false, "collapseScene": false, "collapseNpc": false, "collapseNpcDetail": true, "collapseInterplay": false, "collapseChapter": false, "styleSettings": { "baseFontSize": 14, "fontFamily": "寒蝉全圆体", "interplayStyle": "style2" } };
        const Config = { data: JSON.parse(JSON.stringify(USER_DEFAULT_CONFIG)), load() { this.applyUI(); }, save() { }, updateSetting(key, val) { this.data[key] = val; if (key === 'openMain') { document.getElementById('planner-app').classList.toggle('open', val); } else { render(); } }, updateStyleSetting(key, val) { }, applyUI() { if (this.data.openMain) { document.getElementById('planner-app').classList.add('open'); } else { document.getElementById('planner-app').classList.remove('open'); } this.applyStyleSettings(); }, applyStyleSettings() { const settings = this.data.styleSettings; const rootStyle = document.documentElement.style; rootStyle.setProperty('--base-font-size', settings.baseFontSize + 'px'); }, export() { }, import() { }, resetToDefault() { } };

        const THEMES = ['default', 'milktea', 'macaron'];
        let currentThemeIdx = 0;

        try {
            const savedTheme = localStorage.getItem('echo_theme');
            if (savedTheme && THEMES.includes(savedTheme)) {
                currentThemeIdx = THEMES.indexOf(savedTheme);
                document.documentElement.setAttribute('data-theme', savedTheme);
            }
        } catch (e) { }

        function toggleTheme(e) {
            if (e) e.stopPropagation();
            currentThemeIdx = (currentThemeIdx + 1) % THEMES.length;
            const newTheme = THEMES[currentThemeIdx];
            document.documentElement.setAttribute('data-theme', newTheme);
            try { localStorage.setItem('echo_theme', newTheme); } catch (err) { }
        }

        async function getEntryByKey(key) {
            try {
                const kUpper = key.toUpperCase(); const worldBooks = []; const addBook = (book) => { if (book && !worldBooks.includes(book)) { worldBooks.push(book); } };
                if (typeof getChatLorebook === 'function') try { addBook(await getChatLorebook()); } catch (e) { }
                if (typeof getVariables === 'function') try { const v = await getVariables({ type: 'chat' }); if (v && v.selectedWorldBook) addBook(v.selectedWorldBook); } catch (e) { }
                if (typeof getCharLorebooks === 'function') { try { const b = getCharLorebooks({ type: 'all' }); addBook(b.primary); if (b.additional) b.additional.forEach(addBook); } catch (e) { } } else if (typeof getCurrentCharPrimaryLorebook === 'function') try { addBook(await getCurrentCharPrimaryLorebook()); } catch (e) { }
                if (typeof getLorebookSettings === 'function') try { const s = getLorebookSettings(); if (s && s.selected_global_lorebooks) s.selected_global_lorebooks.forEach(addBook); } catch (e) { }
                if (typeof getLorebookEntries === 'function' && worldBooks.length > 0) {
                    for (const wb of worldBooks) {
                        try { const entries = await getLorebookEntries(wb); if (!entries) continue; for (const entry of entries) { const keys = entry.key || entry.keys; if (keys && Array.isArray(keys)) { if (keys.some(k => k.toUpperCase() === kUpper)) return entry; } } } catch (e) { }
                    }
                }
            } catch (e) { } return null;
        }

        function toggleCard() { const card = document.getElementById('planner-app'); card.classList.toggle('open'); card.querySelector('.toggle-arrow').textContent = card.classList.contains('open') ? '◈' : '✧'; Config.data.openMain = card.classList.contains('open'); }
        function toggleSection(h) { const section = h.parentElement; section.classList.toggle('open'); h.querySelector('.sec-arrow').textContent = section.classList.contains('open') ? '◈' : '✧'; }
        function getRawText() { return document.getElementById('time-capsule').value; }

        const SUPPLEMENT_TAGS = ['file', 'npc_profile', 'npc_inner', 'npc_track', 'npc_jump', 'dm_box'];
        function getTagContent(text, tagName) { const regex = new RegExp(`<${tagName}(?=\\s|>)[^>]*>([\\s\\S]*?)<\\/${tagName}>`, 'i'); const match = text.match(regex); return match ? match[1].trim() : null; }
        function hasSupplementTags(text) { return !!text && SUPPLEMENT_TAGS.some(tag => new RegExp(`<${tag}(?=\\s|>)`, 'i').test(text)); }
        function isUserMessage(msg) { return !!msg && (msg.is_user === true || msg.isUser === true || msg.role === 'user' || msg.type === 'user' || msg.name === 'You'); }
        function extractSupplementCandidateText(value, depth = 0) {
            if (value == null || depth > 2) return '';
            if (typeof value === 'string') return value.trim();
            if (Array.isArray(value)) {
                for (const item of value) {
                    const text = extractSupplementCandidateText(item, depth + 1);
                    if (hasSupplementTags(text)) return text;
                }
                return '';
            }
            if (typeof value === 'object') {
                const preferredKeys = ['text', 'mes', 'message', 'content', 'value', 'data'];
                for (const key of preferredKeys) {
                    if (Object.prototype.hasOwnProperty.call(value, key)) {
                        const text = extractSupplementCandidateText(value[key], depth + 1);
                        if (hasSupplementTags(text)) return text;
                    }
                }
                for (const key of Object.keys(value)) {
                    if (/chat|history|messages|swipes?/i.test(key) || preferredKeys.includes(key)) continue;
                    const text = extractSupplementCandidateText(value[key], depth + 1);
                    if (hasSupplementTags(text)) return text;
                }
            }
            return '';
        }
        function getMessageSupplementText(msg) {
            if (!msg || typeof msg !== 'object') return '';
            const candidatePaths = [
                ['qrf_plot'],
                ['extra', 'qrf_plot'],
                ['extra', 'display_text'],
                ['extra', 'displayText'],
                ['extra', 'text'],
                ['extra', 'mes'],
                ['extra', 'message'],
                ['extra', 'content'],
                ['mes']
            ];
            for (const path of candidatePaths) {
                let current = msg;
                let valid = true;
                for (const key of path) {
                    if (current && typeof current === 'object' && key in current) current = current[key];
                    else {
                        valid = false;
                        break;
                    }
                }
                if (!valid) continue;
                const text = extractSupplementCandidateText(current);
                if (hasSupplementTags(text)) return text;
            }
            return '';
        }
        function getSillyTavernContext() {
            try {
                if (typeof SillyTavern !== 'undefined' && SillyTavern && typeof SillyTavern.getContext === 'function') return SillyTavern.getContext();
                if (typeof window !== 'undefined' && window.SillyTavern && typeof window.SillyTavern.getContext === 'function') return window.SillyTavern.getContext();
            } catch (e) { }
            return null;
        }
        function getCurrentUserLayerMessage() {
            const ctx = getSillyTavernContext();
            const chat = ctx && Array.isArray(ctx.chat) ? ctx.chat : [];
            if (!chat.length) return null;
            for (let i = chat.length - 1; i >= 0; i--) {
                if (isUserMessage(chat[i])) return chat[i];
            }
            return null;
        }
        function getCurrentUserLayerSupplementText() {
            const msg = getCurrentUserLayerMessage();
            if (!msg) return '';
            return getMessageSupplementText(msg);
        }
        function getTagAttr(text, tagName, attrName) { const regex = new RegExp(`<${tagName}(?=\\s|>)[^>]*${attrName}=["']([^"']*)["'][^>]*>`, 'i'); const match = text.match(regex); return match ? match[1].trim() : null; }
        function cleanName(name) { if (!name) return ''; return name.replace(/\uff08.*?\uff09|\(.*?\)/g, '').trim(); }

        // ===== 全局标签扫描（对齐魔法少女的多源抓取策略） =====
        function _collectChatSources() {
            const ctx = getSillyTavernContext();
            const chat = ctx && Array.isArray(ctx.chat) ? ctx.chat : [];
            if (!chat.length) return [];
            const sources = [];
            const _strip = (s) => String(s || '').replace(/<environment_details>[\s\S]*?<\/environment_details>/gi, '').trim();
            const _decode = (s) => s ? s.replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&amp;/g, '&') : '';
            const _stripFence = (s) => (s || '').replace(/^```(?:json|xml|html)?\s*\n?/gm, '').replace(/\n?```\s*$/gm, '').trim();
            for (let i = chat.length - 1; i >= Math.max(0, chat.length - 15); i--) {
                const msg = chat[i];
                if (!msg) continue;
                const raws = [];
                if (msg.extra?.qrf_plot) raws.push(_strip(msg.extra.qrf_plot));
                if (msg.qrf_plot) raws.push(_strip(msg.qrf_plot));
                if (msg.mes) raws.push(_strip(msg.mes));
                if (msg.swipes) {
                    msg.swipes.forEach(s => {
                        if (s?.extra?.qrf_plot) raws.push(_strip(s.extra.qrf_plot));
                        if (s?.mes) raws.push(_strip(s.mes));
                    });
                }
                for (const raw of raws) {
                    const d = _decode(_stripFence(raw));
                    if (d && d.length > 10) sources.push(d);
                }
            }
            return sources;
        }
        function _findTagInChat(tagName, minLen) {
            const sources = _collectChatSources();
            const re = new RegExp(`<${tagName}(?=\\s|>)[^>]*>([\\s\\S]*?)<\\/${tagName}>`, 'i');
            for (const src of sources) {
                const m = src.match(re);
                if (m && m[1] && m[1].trim().length >= (minLen || 10)) return m[1].trim();
            }
            return '';
        }
        function _findSourceWithTags(tagNames) {
            const sources = _collectChatSources();
            for (const src of sources) {
                for (const tag of tagNames) {
                    if (new RegExp(`<${tag}(?=\\s|>)`, 'i').test(src)) return src;
                }
            }
            return '';
        }

        // ===== 文本行解析辅助函数 =====
        function getLineContent(text, key) {
            // 匹配 key: value 或 key[attr]: value
            const regex = new RegExp(`^\\s*${key}(?:\\[(.*?)\\])?[：:]\\s*(.*)$`, 'im');
            const match = text.match(regex);
            return match ? { val: match[2].trim(), attr: match[1] || '' } : { val: '-', attr: '' };
        }

        // ===== 配置化解析工具（from 魔法少女架构） =====
        function _runRegexLadder(content, ladder) {
            for (const re of ladder) {
                const m = content.match(re);
                if (m) return m;
            }
            return null;
        }

        class FallbackChain {
            constructor(label) {
                this.label = label || '';
                this._tries = [];
                this.hitBy = null;
            }
            try(name, fn) {
                this._tries.push({ name, fn });
                return this;
            }
            orElse(fallback) {
                for (const t of this._tries) {
                    let v;
                    try { v = t.fn(); } catch (e) { continue; }
                    if (v !== undefined && v !== null && v !== '' && v !== '-') {
                        this.hitBy = t.name;
                        return v;
                    }
                }
                this.hitBy = '__fallback__';
                return fallback;
            }
        }

        // ===== 字段配置表 =====
        // ACT_FIELD_LADDER 已移除：新格式act只含行为字段(now/beat/initiative/then)，心理字段移入npc_inner

        const TRACK_FIELD_LADDER = {
            now: [
                /^\s*当前动向\s*[:：]\s*(.*)$/im,
                /^\s*我现在在干嘛\s*[:：]\s*(.*)$/im
            ],
            wantBeneath: [
                /^\s*心里惦记\s*[:：]\s*(.*)$/im,
                /^\s*我想要做什么\s*[:：]\s*(.*)$/im
            ],
            social: [/^\s*交际\s*[:：]\s*(.*)$/im],
            cognitive: [
                /^\s*当前认知\s*[:：]\s*(.*)$/im,
                /^\s*我目前知道\s*[:：]\s*(.*)$/im
            ],
            action: [
                /^\s*后续打算\s*[:：]\s*(.*)$/im,
                /^\s*我接下来打算\s*[:：]\s*(.*)$/im
            ],
            plotRelevance: [
                /^\s*前文因果\s*[:：]\s*(.*)$/im,
                /^\s*我跟前文的因果\s*[:：]\s*(.*)$/im
            ],
            entryPrediction: [
                /^\s*预计出场\s*[:：]\s*(.*)$/im,
                /^\s*我什么时候出场\s*[:：]\s*(.*)$/im
            ]
        };

        const PROFILE_FIELD_LADDER = {
            normalLook: [/^\s*平时的样子\s*[:：]\s*(.*)$/im],
            becomeLikeThis: [/^\s*怎么变成这样的\s*[:：]\s*(.*)$/im],
            socialLink: [/^\s*交际\s*[:：]\s*(.*)$/im],
            cognitive: [/^\s*我目前知道\s*[:：]\s*(.*)$/im],
            impression: [/^\s*印象\s*[:：]\s*(.*)$/im],
            state: [/^\s*状态\s*[:：]\s*(.*)$/im]
        };

        const innerFields = '关系|concern(?:\\[L\\])?|inner_voice|aside|stance';
        const innerMulti = (key) => new RegExp(`(?:^|\\n)\\s*${key}\\s*[:：][ \\t]*([\\s\\S]*?)(?=\\n\\s*(?:${innerFields})\\s*[:：]|$)`, 'i');
        const INNER_FIELD_LADDER = {
            relation: [innerMulti('关系'), /^\s*关系\s*[:：][ \t]*(.*)$/im],
            concernL: [innerMulti('concern(?:\\[L\\])?'), /^\s*concern\s*(?:\[L\])?\s*[:：][ \t]*(.*)$/im],
            innerVoice: [innerMulti('inner_voice'), /^\s*inner_voice\s*[:：][ \t]*(.*)$/im],
            aside: [innerMulti('aside'), /^\s*aside\s*[:：][ \t]*(.*)$/im],
            stance: [innerMulti('stance'), /^\s*stance\s*[:：][ \t]*(.*)$/im]
        };

        function renderPlotDetailsHTML(parsedData) {
            let html = '';
            if (parsedData.shortTexts && parsedData.shortTexts.length > 0) html += '<div class="cell-tags">' + parsedData.shortTexts.map(t => '<span class="cell-tag">' + t + '</span>').join('') + '</div>';
            if (parsedData.longTexts && parsedData.longTexts.length > 0) html += '<div class="plot-detail-card"><div class="plot-section-title">轨迹重演</div>' + parsedData.longTexts.map(t => '<p class="plot-summary-content">' + t + '</p>').join('') + '</div>';
            if (parsedData.dialogue) {
                const dialogueRegex = /(?:([\u4e00-\u9fa5a-zA-Z0-9_]+)\s*[:：]\s*["'“‘「『](.*?)['"’”」』])|(?:["'“‘「『](.*?)['"’”」』]\s*[（(]([\u4e00-\u9fa5a-zA-Z0-9_]+)[)）])/g;
                let match, list = '', last = null, side = 'right';
                while ((match = dialogueRegex.exec(parsedData.dialogue)) !== null) {
                    const sp = (match[1] || match[4]).trim();
                    const content = (match[2] || match[3]).trim();
                    if (last !== sp) { side = (side === 'right' ? 'left' : 'right'); last = sp; }
                    list += '<div class="dialogue-bubble speaker-' + side + '"><div class="dialogue-speaker">' + sp + '</div><div class="dialogue-content">' + content + '</div></div>';
                }
                if (list) html += '<div class="plot-detail-card"><div class="plot-section-title">心声低语</div><div class="plot-dialogue-list">' + list + '</div></div>';
            }
            return '<div class="plot-details-wrapper">' + html + '</div>';
        }

        async function togglePlotMemory(code, readerId) {
            const panel = document.getElementById(readerId); const allTags = document.querySelectorAll('.plot-tag');
            allTags.forEach(t => { if (t.innerText !== code) t.classList.remove('active'); });
            let currentTag = Array.from(allTags).find(t => t.innerText === code);
            if (currentTag && currentTag.classList.contains('active')) { currentTag.classList.remove('active'); panel.classList.remove('show'); return; }
            const entry = await getEntryByKey(code);
            if (!entry || !entry.content) { if (currentTag) currentTag.classList.remove('active'); panel.classList.remove('show'); return; }
            if (currentTag) currentTag.classList.add('active'); panel.classList.add('show');
            panel.innerHTML = `<div class="plot-reader-header"><span class="plot-reader-id">${code}</span></div><div class="plot-reader-content"><span class="loading-tip">✦ 正在回溯记忆...</span></div>`;
            setTimeout(() => {
                const parsedData = parsePlotMemory(entry.content);
                panel.querySelector('.plot-reader-content').innerHTML = parsedData ? renderPlotDetailsHTML(parsedData) : `<div style="white-space:pre-wrap; padding: 0 15px 15px;">${entry.content}</div>`;
            }, 50);
        }


        function parsePlotMemory(content) {
            let c = content.trim(); if (c.startsWith('|')) c = c.substring(1); if (c.endsWith('|')) c = c.slice(0, -1); const parts = c.split('|').map(p => p.trim()).filter(p => p); if (parts.length === 0) return null;
            const r = { shortTexts: [], longTexts: [], dialogue: '' };
            parts.forEach(p => { if (/^AM\d+$/i.test(p)) return; if (/[\u4e00-\u9fa5a-zA-Z0-9_]+\s*[:：]\s*[‘'"“「『]/.test(p) || /[‘'"“「『].+?['"’”」』]\s*[（(][\u4e00-\u9fa5a-zA-Z0-9_]+[)）]/.test(p)) r.dialogue = p; else if (p.length <= 50) r.shortTexts.push(p); else r.longTexts.push(p); });
            return r;
        }



        function switchNpcView(clickedEl) {
            const container = clickedEl.closest('.sec-content');
            const npcName = clickedEl.getAttribute('data-npc-name');
            const isActive = clickedEl.classList.contains('active');

            // 1. 如果没有详情，直接返回
            if (clickedEl.classList.contains('no-detail')) return;

            // 2. 清除该区域所有激活状态
            container.querySelectorAll('.npc-selector .person-nameplate').forEach(el => el.classList.remove('active'));
            container.querySelectorAll('.npc-details-container .npc-card-wrapper').forEach(card => card.classList.remove('active'));

            // 3. 如果点击的是原本激活的，则到此为止（实现关闭效果）
            if (isActive) return;

            // 4. 激活当前点击的
            clickedEl.classList.add('active');
            const targetCard = document.getElementById(`npc-card-content-${npcName.replace(/ /g, '_')}`);
            if (targetCard) targetCard.classList.add('active');
        }

        function render() { const t = getRawText(); if (t) renderPlannerMode(t); }

        function renderPlannerMode(text) {
            // 当前态只从正则注入文本读取；长期记录只从当前最新用户楼层完整消息读取。
            const stageContent = getTagContent(text, 'stage') || '';
            const dmtrackContent = getTagContent(text, 'dmtrack') || '';
            const supplementText = getCurrentUserLayerSupplementText();
            const fileRawContent = _findTagInChat('file', 50) || getTagContent(supplementText, 'file') || '';
            const dmBoxRawContent = _findTagInChat('dm_box', 10) || getTagContent(supplementText, 'dm_box') || '';

            let sdContent = getTagContent(dmtrackContent, 'scene') || getTagContent(text, 'scene') || '';

            // 从 <stage> 底部解析时间线行: Day X, HH:MM | 场景简述 | 天气=XX | 在场: NPC名
            let stageTimeline = { day: '', time: '', sceneSummary: '', weather: '', present: '' };
            if (stageContent) {
                const timelineMatch = stageContent.match(/^\s*([^,，|｜\n]+?)(?:[,，]\s*|\s+)(\d{1,2}:\d{2})(?:\s*[|｜]\s*(.+))?$/im);
                if (timelineMatch) {
                    stageTimeline.day = timelineMatch[1].trim();
                    stageTimeline.time = timelineMatch[2].trim();
                    if (timelineMatch[3]) {
                        const parts = timelineMatch[3].split(/[|｜]/);
                        parts.forEach(p => {
                            const pt = p.trim();
                            const wm = pt.match(/天气\s*[=＝]\s*(.+)/);
                            const pm = pt.match(/在场\s*[:：]\s*(.+)/);
                            if (wm) stageTimeline.weather = wm[1].trim();
                            else if (pm) stageTimeline.present = pm[1].trim();
                            else if (!stageTimeline.sceneSummary) stageTimeline.sceneSummary = pt;
