            }

            // 从 <scene> 第一行解析时间线（新格式优先）
            let sceneTimeline = { day: '', time: '', sceneSummary: '', weather: '', present: '' };
            if (sdContent) {
                const firstLine = sdContent.split('\n')[0];
                const stMatch = firstLine.match(/^\s*([^,，|｜\n]+?)(?:[,，]\s*|\s+)(\d{1,2}:\d{2})(?:\s*[|｜]\s*(.+))?$/i);
                if (stMatch) {
                    sceneTimeline.day = stMatch[1].trim();
                    sceneTimeline.time = stMatch[2].trim();
                    if (stMatch[3]) {
                        stMatch[3].split(/[|｜]/).forEach(p => {
