                            else if (pm) sceneTimeline.present = pm[1].trim();
                            else if (!sceneTimeline.sceneSummary) sceneTimeline.sceneSummary = pt;
                        });
                    }
                }
            }


            // 1. 解析 Timestamp

            let chronoHTML = '';

            const chronoMatch = sdContent.match(/【时空】(.*?)(?=\s*[|｜\n]|$)/i);
            const tsRaw = chronoMatch ? chronoMatch[1].trim() : '';
            let chronoHeaderHTML = '';

            // 优先级：sceneTimeline > 【时空】> stageTimeline
            const effectiveDay = (sceneTimeline.day && sceneTimeline.time ? `${sceneTimeline.day}, ${sceneTimeline.time}` : '')
                || tsRaw
                || (stageTimeline.day && stageTimeline.time ? `${stageTimeline.day}, ${stageTimeline.time}` : '');

            // 解析跳跃字段
            const sceneSkipMatch = sdContent.match(/跳跃\s*[=＝]\s*([^|｜\n]+)/i);
            const skipBadge = (sceneSkipMatch && sceneSkipMatch[1].trim() !== '无') ? `<div class="info-badge delta-style">${sceneSkipMatch[1].trim()}</div>` : '';

            // 月相盘始终显示
            const moonBoxHTML = `<div class="moon-box" onclick="toggleTheme(event)"><div class="moon-orb"></div><div class="star-dust s1">✦</div><div class="star-dust s2">✧</div></div>`;

            if (effectiveDay) {
