                chronoHeaderHTML = `${moonBoxHTML}<div class="time-readout"${timeStyle}>${timeText}</div><div class="chrono-info-group">${dayText ? `<div class="info-badge day-style">${dayText}</div>` : ''}${skipBadge}${deltaText ? `<div class="info-badge delta-style">${deltaText}</div>` : ''}</div>`;
