            // 解析 Chapter & 时空板块
            let chapterStatusHTML = '';

            // 只要发现 时空 / 场景 等标签或scene第一行有时间线，就渲染该板块
            if (/【时空】|【场景】/.test(sdContent) || sceneTimeline.day) {

                //  通用字段提取器 
