            // 3. 解析 Entry Eval：仅从 <stage> 底部时间线读取 "在场: NPC名"
            let entryEvalHTML = '';
            let entryP = sceneTimeline.present || stageTimeline.present || '无', entryE = '无';

            let entryItemsHTML = '';
            if (entryP && entryP !== '无' && entryP !== '-') entryItemsHTML += `<div class="entry-eval-row"><span class="entry-eval-key">在场</span><span class="entry-eval-val">${entryP}</span></div>`;
            if (entryE && entryE !== '无' && entryE !== '-') entryItemsHTML += `<div class="entry-eval-row"><span class="entry-eval-key">变动</span><span class="entry-eval-val">${entryE}</span></div>`;

            if (entryItemsHTML) {
                entryEvalHTML = `<div class="entry-eval-box">${entryItemsHTML}</div>`;
