            // 4. 解析登场 NPC：最新格式只读取 <stage> 内的 <act>
            const npcActionContent = stageContent;
            const npcList = [];
            const npcRegex = /<act\s+name=["'\u201c]([^'\u201d"]+)["'\u201d]([^>]*)>([\s\S]*?)<\/act>/gi;

            let nm;
            while ((nm = npcRegex.exec(npcActionContent)) !== null) {
                const name = cleanName(nm[1]);
                const attrs = nm[2];
                const rawBody = nm[3];
                const body = rawBody.replace(/<!--[\s\S]*?-->/g, '');

                const getAttr = (str, key) => {
                    const reg = new RegExp(`${key}[=\uff1d](?:["'\u201c]([^"'\u201d]+)["'\u201d]|([^\\s>]+))`);
                    const m = str.match(reg);
                    return m ? (m[1] || m[2]) : '-';
                };


                // act只保留行为字段解析(now/beat/initiative/then)
                const FIELD_NAMES = 'now|beat|then|initiative';
                const multiLineFieldRegex = (key) => new RegExp(`(?:^|\\n)\\s*${key}\\s*[:：]\\s*([\\s\\S]*?)(?=\\n\\s*(?:${FIELD_NAMES})(?:\\s*\\[|\\s*[:：])|$)`, 'i');

                const nMatch = body.match(multiLineFieldRegex('now'));
                const btMatch = body.match(multiLineFieldRegex('beat'));
                const thMatch = body.match(multiLineFieldRegex('then'));

                let now = nMatch ? nMatch[1].trim().replace(/\n+/g, '\n') : '-';
                let beat = btMatch ? btMatch[1].trim().replace(/\n+/g, '\n') : '-';
                let then = thMatch ? thMatch[1].trim().replace(/\n+/g, '\n') : '-';

                // Fallback for Secondary NPC: now/beat/then: 简写
                const nbtMatch = body.match(/^\s*now\/beat\/then\s*[:：]\s*(.*)$/im);
                if (nbtMatch) {
                    const combined = nbtMatch[1].trim();
                    if (now === '-') now = combined;
                    if (beat === '-') beat = combined;
                    if (then === '-') then = combined;
                }

                // Initiative
                const initMatch = body.match(new RegExp(`(?:^|\\n)\\s*initiative(?:\\s*\\[(.*?)\\])?\\s*[:：]\\s*([\\s\\S]*?)(?=\\n\\s*(?:${FIELD_NAMES})(?:\\s*\\[|\\s*[:：])|$)`, 'i'));
                const initAttr = initMatch && initMatch[1] ? initMatch[1].trim() : '';
                const initVal = initMatch && initMatch[2] ? initMatch[2].trim().replace(/\n+/g, '\n') : '-';

