                    name,
                    now, beat, then,
                    init: initVal, initType: initAttr
                });
            }

            // 4b. 解析 <npc_inner> 标签，合并心理字段到已有 npcList（仅当前态来源，避免缓存层错位污染）
            const npcInnerSource = [stageContent, text].filter(Boolean).join('\n');
            const npcInnerRegex = /<npc_inner\s+name=["'\u201c]([^'\u201d"]+)["'\u201d][^>]*>([\s\S]*?)<\/npc_inner>/gi;
