            }

            // 5. 生成 NPC 卡片
            let npcCardsHTML = '', npcSelectorsHTML = '';
            if (npcList.length > 0) {
                // 默认不展开任何NPC详情
                npcSelectorsHTML = npcList.map(n => `<span class="person-nameplate" data-npc-name="${n.name.replace(/ /g, '_')}" onclick="switchNpcView(this)">${n.name}</span>`).join('');

