            // 6. 解析 Offstage (已重构，移至 file 提取部分)

            // 7. 解析 Scene & Dynamics 全部移除


            // 8. 解析 Recall & Files (保持不变)
            const recallRaw = getTagContent(text, 'recall') || '';
            const plots = (recallRaw.match(/AM\d+/gi) || []);

            // ===== 4. 旋律手稿 & 念念不忘 & 视界之外：从当前用户楼层补充源提取 =====
            const combinedOffSource = _findSourceWithTags(['npc_track', 'npc_jump']) || supplementText;

            //  提取 视界之外：读取当前用户楼层内的 <npc_track> 
