                    const pr = (_runRegexLadder(body, TL.plotRelevance) || [])[1]?.trim() || '-';
                    const ep = (_runRegexLadder(body, TL.entryPrediction) || [])[1]?.trim() || '-';

                    const predHtml = ep !== '-' ? `<span class="npc-badge" style="margin-left:auto; background:var(--ui-color-sec); color:var(--text-sub); font-weight:normal; white-space:normal; flex-shrink:1; word-break:break-word; text-align:right; max-width:70%;">${ep}</span>` : '';

                    let contentHtml = '';
                    if (n !== '-' || wb !== '-' || soc !== '-' || kn !== '-' || un !== '-' || aa !== '-' || pr !== '-') {
                        contentHtml = `<div class="npc-group">` +
                            (n !== '-' ? `<div class="npc-row"><span class="npc-row-label">当前</span><span class="npc-row-val">${n}</span></div>` : '') +
                            (wb !== '-' ? `<div class="npc-row"><span class="npc-row-label">意图</span><span class="npc-row-val">${wb}</span></div>` : '') +
                            (soc !== '-' ? `<div class="npc-row"><span class="npc-row-label">交际</span><span class="npc-row-val">${soc}</span></div>` : '') +
                            (kn !== '-' && kn !== '' ? `<div class="npc-row"><span class="npc-row-label">已知</span><span class="npc-row-val">${kn}</span></div>` : '') +
                            (un !== '-' && un !== '' ? `<div class="npc-row"><span class="npc-row-label">未知</span><span class="npc-row-val">${un}</span></div>` : '') +
                            (aa !== '-' ? `<div class="npc-row"><span class="npc-row-label">行动</span><span class="npc-row-val">${aa}</span></div>` : '') +
                            (pr !== '-' ? `<div class="npc-row"><span class="npc-row-label">关联</span><span class="npc-row-val">${pr}</span></div>` : '') +
                            `</div>`;
                    } else if (body.trim().length > 0) {
                        contentHtml = `<div class="npc-group"><div class="npc-row"><span class="npc-row-val" style="color:var(--text-sub);white-space:pre-wrap;">${body.trim()}</span></div></div>`;
                    }

                    if (contentHtml) {
                        offItems += `<div class="npc-card-wrapper active" style="margin-bottom:10px;"><div class="npc-card"><div class="npc-header"><span class="npc-name" style="background:none;-webkit-text-fill-color:initial;color:var(--text-sub);">${name}</span>${predHtml}</div>${contentHtml}</div></div>`;
                    }
                }

                if (offItems) {
                    offstageHTML = `<style>#offstage-section .npc-name::before{background:none!important;-webkit-text-fill-color:initial!important;color:var(--text-sub)!important;}</style><div class="section offstage-section" id="offstage-section"><div class="sec-header" onclick="toggleSection(this)"><span class="sec-title">视界之外</span><span class="sec-arrow">✧</span></div><div class="sec-content"><div class="offstage-grid">${offItems}</div></div></div>`;
                }
            }

            //  提取 弦外之音：读取当前用户楼层内的 <npc_jump> 与 <npc_profile> 
            let overtonesHTML = '';
            if (combinedOffSource) {
                // 最新格式：读取 <npc_jump>
                let timeskipHTML = '';
                let tskRowsHTML = '';
                let commonDuration = '';

                const jumpRegex = /<npc_jump\s+name=["'“]([^'"”]+)["'”]\s+跃过时间=["'“]([^'"”]+)["'”][^>]*>([\s\S]*?)<\/npc_jump>/gi;
                let jumpMatch;
                while ((jumpMatch = jumpRegex.exec(combinedOffSource)) !== null) {
                    const tName = cleanName(jumpMatch[1]);
                    const duration = jumpMatch[2].trim();
                    const body = jumpMatch[3].replace(/<!--[\s\S]*?-->/g, '');

                    if (!commonDuration) commonDuration = duration;

                    let propsHTML = '';
                    body.split('\n').filter(l => l.trim()).forEach(line => {
                        const m = line.match(/^\s*(.+?)[:：]\s*(.*)/);
                        if (m) {
                            let key = m[1].trim();
                            let val = m[2].trim();
                            let dispKey = key;
                            if (key.includes('干嘛') || key.includes('期间') || key.includes('动向')) dispKey = '动向';
                            else if (key.includes('心情')) dispKey = '心境';
                            else if (key.includes('状态')) dispKey = '状态';
                            else if (key.includes('主角')) dispKey = '主角';
                            else if (key.includes('交际')) dispKey = '交际';
                            else if (key.includes('个人') || key.includes('个人线')) dispKey = '自身';
                            else if (key.includes('在忙') || key.includes('进展')) dispKey = '在忙';
                            else dispKey = key.slice(0, 3);

                            propsHTML += `<div class="npc-row"><span class="npc-row-label">${dispKey}</span><span class="npc-row-val">${val}</span></div>`;
                        }
                    });

                    tskRowsHTML += `<div style="margin-bottom:16px;">
                        <div style="margin-bottom:8px;"><span class="npc-badge">${tName}</span></div>
                        <div style="display:flex; flex-direction:column; padding-left:2px;">
                            ${propsHTML}
                        </div>
                    </div>`;
                }

                if (tskRowsHTML) {
                    timeskipHTML = `<div class="npc-card-wrapper active" style="margin-bottom:10px;"><div class="npc-group" style="padding:12px;">
                        <div style="display:flex; justify-content:space-between; align-items:flex-start; margin-bottom:12px;">
                            <div class="npc-group-label" style="margin-bottom:0;">时空流转</div>
                            ${commonDuration ? `<span class="npc-badge">${commonDuration}</span>` : ''}
                        </div>
                        <div style="display:flex; flex-direction:column;">${tskRowsHTML}</div>
                    </div></div>`;
                }

                // 1. 提取 <npc_profile>
                const trpgNotes = [];
                const trpgRegex = /<npc_profile\s+name=["'“]([^'"”]+)["'”][^>]*>([\s\S]*?)<\/npc_profile>/gi;
                let trpgMatch;
                while ((trpgMatch = trpgRegex.exec(combinedOffSource)) !== null) {
                    const npcName = cleanName(trpgMatch[1]);
                    const flag = '';
                    const rawBody = trpgMatch[2];
                    const body = rawBody.replace(/<!--[\s\S]*?-->/g, '');

                    // 使用配置化解析
                    const PL = PROFILE_FIELD_LADDER;
                    const normalLook = (_runRegexLadder(body, PL.normalLook) || [])[1]?.trim() || '-';
                    const becomeLikeThis = (_runRegexLadder(body, PL.becomeLikeThis) || [])[1]?.trim() || '-';
                    const socialLink = (_runRegexLadder(body, PL.socialLink) || [])[1]?.trim() || '-';
                    const cogLine = (_runRegexLadder(body, PL.cognitive) || [])[1]?.trim() || '-';
                    let known = '-', unknown = '-';
                    if (cogLine !== '-') {
                        const unMatch = cogLine.match(/(.*?)(?:[|｜]\s*(?:未知的|还没搞懂的|还不知道的|未知的=)\s*[:：=＝]?\s*(.*))$/);
                        if (unMatch) {
                            known = unMatch[1].replace(/^\s*(?:确知的|听说的|怀疑的|我目前知道|确知\/听说\/怀疑的内容附来源)\s*[=＝]?\s*/, '').trim();
                            unknown = unMatch[2].replace(/^\s*(?:未知的|还没搞懂的|还不知道的)\s*[=＝]?\s*/, '').trim();
                        } else {
                            known = cogLine.replace(/^\s*(?:确知的|听说的|怀疑的|我目前知道|确知\/听说\/怀疑的内容附来源)\s*[=＝]?\s*/, '').trim();
                        }
                    }

                    const impressionLine = (_runRegexLadder(body, PL.impression) || [])[1]?.trim() || '';
                    let impPlus = '-', impMinus = '-', impFavor = '-';
                    const ipMatchProfile = impressionLine.match(/\+([^-|｜\n]+)/);
                    if (ipMatchProfile) impPlus = ipMatchProfile[1].trim();
                    const imMatch = impressionLine.match(/-([^|｜\n]+)/);
                    if (imMatch) impMinus = imMatch[1].trim();
                    const favorMatch = impressionLine.match(/好感\s*[=＝]\s*([^|｜\n]+)/);
                    if (favorMatch) impFavor = favorMatch[1].trim();

                    const stateLine = (_runRegexLadder(body, PL.state) || [])[1]?.trim() || '';
                    const energy = (stateLine.match(/社交能量\s*[=＝]\s*([^|｜\n]+)/) || [])[1] || '-';
                    const health = (stateLine.match(/身体\s*[=＝]\s*([^|｜\n]+)/) || [])[1] || '-';
                    const behavior = (stateLine.match(/表现\s*[=＝]\s*([^|｜\n]+)/) || [])[1] || '-';
                    // 新增：从状态行提取情绪
                    const emotionInState = (stateLine.match(/情绪\s*[=＝]\s*\[?([^\]|｜\n]+)\]?/) || [])[1] || '-';

                    let initReviewContent = '';

                    // 新增: 印象消化后的态度行（印象标签下面的独立文本行）
                    let impressionDigest = '-';
                    const impDigestMatch = body.match(/印象[:：].*\n+\s*(.+?)(?:\n|$)/im);
                    if (impDigestMatch) {
                        const candidate = impDigestMatch[1].trim();
                        // 排除掉下一个字段（如 "状态:"）
                        if (candidate && !/^(?:状态|关系|concern|inner_voice|aside|stance|印象)/.test(candidate)) {
                            impressionDigest = candidate;
                        }
                    }
                    trpgNotes.push({
                        name: npcName, flag,
                        normalLook, becomeLikeThis,
                        socialLink,
                        profileRelation: '-', profileConcernL: '-', profileInnerVoice: '-', profileAside: '-', profileStance: '-',
                        known, unknown,
                        impPlus, impMinus, impFavor, impressionDigest,
                        energy, health, behavior,
                        reviewContent: initReviewContent
                    });
                }

                // 从 <npc_inner> 标签补充 trpgNotes 中的心理字段（新格式：npc_inner 与 npc_profile 同级）
                const trpgInnerRegex = /<npc_inner\s+name=["'\u201c]([^'\u201d"]+)["'\u201d][^>]*>([\s\S]*?)<\/npc_inner>/gi;
                let trpgInnerMatch;
                while ((trpgInnerMatch = trpgInnerRegex.exec(combinedOffSource)) !== null) {
                    const innerName = cleanName(trpgInnerMatch[1]);
                    const innerBody = trpgInnerMatch[2].replace(/<!--[\s\S]*?-->/g, '');
                    const IL = INNER_FIELD_LADDER;

                    let target = trpgNotes.find(n => n.name === innerName);
                    if (!target) {
                        target = {
                            name: innerName, flag: '',
                            normalLook: '-', becomeLikeThis: '-',
                            socialLink: '-',
                            profileRelation: '-', profileConcernL: '-', profileInnerVoice: '-', profileAside: '-', profileStance: '-',
                            known: '-', unknown: '-',
                            impPlus: '-', impMinus: '-', impFavor: '-', impressionDigest: '-',
                            energy: '-', health: '-', behavior: '-',
                            reviewContent: ''
                        };
                        trpgNotes.push(target);
                    }

                    target.profileRelation = (_runRegexLadder(innerBody, IL.relation) || [])[1]?.trim() || '-';
                    target.profileConcernL = (_runRegexLadder(innerBody, IL.concernL) || [])[1]?.trim() || '-';
                    target.profileInnerVoice = (_runRegexLadder(innerBody, IL.innerVoice) || [])[1]?.trim() || '-';
                    target.profileAside = (_runRegexLadder(innerBody, IL.aside) || [])[1]?.trim() || '-';
                    target.profileStance = (_runRegexLadder(innerBody, IL.stance) || [])[1]?.trim() || '-';
                }

                // 生成 TRPG Notes HTML
                let trpgHTML = '';
                if (trpgNotes.length > 0) {
                    trpgHTML = trpgNotes.map(n => {
                        let reviewHtml = '';
                        if (n.reviewContent) {
                            const parseDialogue = (textContent) => {
                                const dialoguePattern = /\[([^\]]+)\]\s*([\s\S]*?)(?=\[[^\]]+\]|$)/gi;
                                let dialogueMatch;
                                const bubbles = [];
                                let lastSpeaker = null;
                                let side = 'right';
                                while ((dialogueMatch = dialoguePattern.exec(textContent)) !== null) {
                                    const speaker = dialogueMatch[1];
                                    const content = dialogueMatch[2].trim();
                                    if (content) {
                                        if (speaker === '阿尔') side = 'left';
                                        else if (speaker === '爱德华') side = 'right';
                                        else if (speaker !== lastSpeaker && lastSpeaker !== null) side = side === 'left' ? 'right' : 'left';
                                        lastSpeaker = speaker;
                                        const escDiv = document.createElement('div');
                                        escDiv.textContent = content;
                                        bubbles.push(`<div class="dialogue-bubble speaker-${side}"><div class="dialogue-speaker">${speaker}</div><div class="dialogue-content">${escDiv.innerHTML}</div></div>`);
                                    }
                                }
                                return bubbles.length > 0 ? `<div class="plot-dialogue-list" style="margin-top:15px; margin-bottom:5px;">${bubbles.join('')}</div>` : '';
                            };

                            const bubblesHtml = parseDialogue(n.reviewContent);
                            if (bubblesHtml) {
                                reviewHtml = bubblesHtml;
                            } else {
                                const escDiv = document.createElement('div');
                                escDiv.textContent = n.reviewContent;
                                reviewHtml = `<div style="font-size:calc(var(--base-font-size) - 2px); color:var(--text-sub); white-space:pre-wrap; line-height:1.6; margin-top:15px; margin-bottom:5px;">${escDiv.innerHTML}</div>`;
                            }
                        }

                        const effectiveFlag = n.flag.includes('/') ? n.flag.split('/')[0].trim() : n.flag;
                        let mappedFlag = n.flag;
                        if (effectiveFlag === 'I') mappedFlag = '初登场';
                        else if (effectiveFlag === 'U') mappedFlag = '有更新';
                        else if (effectiveFlag === 'M') mappedFlag = '无变化';

                        const escapeInline = (value) => {
                            const div = document.createElement('div');
                            div.textContent = value || '';
                            return div.innerHTML;
                        };
                        const innerRows = [];
                        if (n.profileRelation !== '-') innerRows.push(`<div class="npc-field"><span class="npc-field-label">关系</span><span class="npc-field-val">${escapeInline(n.profileRelation)}</span></div>`);
                        if (n.profileConcernL !== '-') innerRows.push(`<div class="npc-field"><span class="npc-field-label">惦记</span><span class="npc-field-val">${escapeInline(n.profileConcernL)}</span></div>`);
                        if (n.profileInnerVoice !== '-') innerRows.push(`<div class="npc-field"><span class="npc-field-label">心声</span><span class="npc-field-val">${escapeInline(n.profileInnerVoice)}</span></div>`);
                        if (n.profileStance !== '-') innerRows.push(`<div class="npc-field"><span class="npc-field-label">立场</span><span class="npc-field-val">${escapeInline(n.profileStance)}</span></div>`);
                        if (n.profileAside !== '-') innerRows.push(`<div class="npc-field"><span class="npc-field-label">旁白</span><span class="npc-field-val">${escapeInline(n.profileAside)}</span></div>`);
                        const innerWorldHTML = innerRows.length ? `<div class="npc-group">
                                <div class="npc-group-label" style="margin-bottom:8px;">内心世界</div>
                                <div class="npc-grid-2col">${innerRows.join('')}</div>
                            </div>` : '';

                        return `<div class="npc-card-wrapper" id="npc-card-content-${n.name.replace(/ /g, '_')}_trpg" style="margin-bottom:10px;"><div class="npc-card" style="box-shadow:none;">
                            <div class="npc-header">
                                <span class="npc-name" style="background:none; -webkit-text-fill-color:initial; color:var(--theme-color-1); font-size:calc(var(--base-font-size) + 1px);">${n.name}</span>
                                <div class="npc-badge-row">
                                    ${mappedFlag ? `<span class="npc-badge">${mappedFlag}</span>` : ''}
                                </div>
                            </div>

                            ${(n.normalLook !== '-' || n.becomeLikeThis !== '-') ? `<div class="npc-group">
                                <div class="npc-group-label" style="margin-bottom:8px;">角色基底</div>
                                <div style="display:flex; flex-direction:column;">
                                    ${n.normalLook !== '-' ? `<div class="npc-row"><span class="npc-row-label">表象</span><span class="npc-row-val">${n.normalLook}</span></div>` : ''}
                                    ${n.becomeLikeThis !== '-' ? `<div class="npc-row"><span class="npc-row-label">形成</span><span class="npc-row-val">${n.becomeLikeThis}</span></div>` : ''}
                                </div>
                            </div>` : ''}

                            ${(n.socialLink !== '-') ? `<div class="npc-group">
                                <div class="npc-group-label" style="margin-bottom:8px;">当下动态</div>
                                <div class="npc-grid-2col">
                                    ${n.socialLink !== '-' ? `<div class="npc-field"><span class="npc-field-label">交际</span><span class="npc-field-val">${n.socialLink}</span></div>` : ''}
                                </div>
                            </div>` : ''}

                            ${(n.known !== '-' || n.unknown !== '-') ? `<div class="npc-group">
                                <div class="npc-group-label" style="margin-bottom:8px;">当下认知</div>
                                <div class="npc-grid-2col">
                                    ${n.known !== '-' ? `<div class="npc-field"><span class="npc-field-label">已知</span><span class="npc-field-val">${n.known}</span></div>` : ''}
                                    ${n.unknown !== '-' ? `<div class="npc-field"><span class="npc-field-label">未知</span><span class="npc-field-val">${n.unknown}</span></div>` : ''}
                                </div>
                            </div>` : ''}

                            ${innerWorldHTML}

                            ${(n.impPlus !== '-' || n.impMinus !== '-' || n.impFavor !== '-' || n.energy !== '-' || n.health !== '-' || (n.behavior !== '-' && n.behavior !== undefined) || n.impressionDigest !== '-') ? `<div class="npc-group">
                                <div class="npc-group-label" style="margin-bottom:8px;">印象状态</div>
                                <div class="npc-grid-2col">
                                    ${n.impPlus !== '-' ? `<div class="npc-field"><span class="npc-field-label">加分</span><span class="npc-field-val">${n.impPlus}</span></div>` : ''}
                                    ${n.impMinus !== '-' ? `<div class="npc-field"><span class="npc-field-label">减分</span><span class="npc-field-val">${n.impMinus}</span></div>` : ''}
                                    ${n.impFavor !== '-' ? `<div class="npc-field"><span class="npc-field-label">好感</span><span class="npc-field-val">${n.impFavor}</span></div>` : ''}
                                    ${n.energy !== '-' ? `<div class="npc-field"><span class="npc-field-label">能量</span><span class="npc-field-val">${n.energy}</span></div>` : ''}
                                    ${n.health !== '-' ? `<div class="npc-field"><span class="npc-field-label">身体</span><span class="npc-field-val">${n.health}</span></div>` : ''}
                                    ${n.behavior !== '-' && n.behavior !== undefined ? `<div class="npc-field"><span class="npc-field-label">表现</span><span class="npc-field-val">${n.behavior}</span></div>` : ''}
                                    ${n.impressionDigest !== '-' ? `<div class="npc-field"><span class="npc-field-val" style="color:var(--text-sub);font-size:calc(var(--base-font-size) - 2px);font-style:italic;">${n.impressionDigest}</span></div>` : ''}
                                </div>
                            </div>` : ''}
                            ${reviewHtml}
                        </div></div>`;
                    }).join('');
                    const trpgSelectorsHTML = trpgNotes.map(n => `<span class="person-nameplate" data-npc-name="${n.name.replace(/ /g, '_')}_trpg" onclick="switchNpcView(this)">${n.name}</span>`).join('');
                    trpgHTML = `<div class="npc-selector">${trpgSelectorsHTML}</div><div class="npc-details-container">${trpgHTML}</div>`;
                }

                if (trpgHTML || timeskipHTML) {
                    overtonesHTML = `<div class="section"><div class="sec-header" onclick="toggleSection(this)"><span class="sec-title">弦外之音</span><span class="sec-arrow">✧</span></div><div class="sec-content" style="padding-top:15px;">${timeskipHTML}${trpgHTML}</div></div>`;
                }
            }

            // 4b. 念念不忘：显示 file、npc_track/npc_jump 与 dm_box 原始内容
            let fileContentHTML = '';
            const npcTrackJumpRawContent = (() => {
                const source = _findSourceWithTags(['npc_track', 'npc_jump']) || supplementText;
                if (!source) return '';
                const blocks = [];
                const regex = /<(npc_track|npc_jump)(?=\s|>)[^>]*>[\s\S]*?<\/\1>/gi;
                let match;
                while ((match = regex.exec(source)) !== null) {
                    if (match[0] && match[0].trim()) blocks.push(match[0].trim());
                }
                return blocks.join('\n\n');
            })();

            if (fileRawContent || npcTrackJumpRawContent || dmBoxRawContent) {
                let combinedHTML = '';
                if (fileRawContent) {
                    const tempDiv = document.createElement('div');
                    tempDiv.textContent = fileRawContent;
                    combinedHTML += `<div class="file-raw-content" style="white-space: pre-wrap; word-wrap: break-word; margin: 0; font-family: var(--main-font-family); font-size: calc(var(--base-font-size) - 2px); line-height: 1.6; color: var(--text-main);">${tempDiv.innerHTML}</div>`;
                }
                if (npcTrackJumpRawContent) {
                    const tempDivTrackJump = document.createElement('div');
                    tempDivTrackJump.textContent = npcTrackJumpRawContent;
                    const separator = combinedHTML ? `<div style="height: 1px; background: var(--ui-color-sec); margin: 12px 0;"></div>` : '';
                    combinedHTML += separator + `<div class="npc-track-jump-raw-content" style="white-space: pre-wrap; word-wrap: break-word; margin: 0; font-family: var(--main-font-family); font-size: calc(var(--base-font-size) - 2px); line-height: 1.6; color: var(--text-main);">${tempDivTrackJump.innerHTML}</div>`;
                }
                if (dmBoxRawContent) {
                    const tempDiv2 = document.createElement('div');
                    tempDiv2.textContent = dmBoxRawContent;
                    const separator = combinedHTML ? `<div style="height: 1px; background: var(--ui-color-sec); margin: 12px 0;"></div>` : '';
                    combinedHTML += separator + `<div class="dm-box-raw-content" style="white-space: pre-wrap; word-wrap: break-word; margin: 0; font-family: var(--main-font-family); font-size: calc(var(--base-font-size) - 2px); line-height: 1.6; color: var(--theme-color-1);">${tempDiv2.innerHTML}</div>`;
                }

                fileContentHTML = `<div class="section offstage-section"><div class="sec-header" onclick="toggleSection(this)"><span class="sec-title">念念不忘</span><span class="sec-arrow">✧</span></div><div class="sec-content">${combinedHTML}</div></div>`;
            }
            // 4c. 旋律手稿：结构化解析 dm_box 中的主线、暗线、个人线和下轮注意
            let dmBoxHTML = '';
            if (dmBoxRawContent) {
                // 清洗并标准化换行
                let cleanDm = dmBoxRawContent.replace(/<!--[\s\S]*?-->/g, '').replace(/<br\s*\/?>/gi, '\n').replace(/<\/?p>/gi, '\n').trim();
                cleanDm = cleanDm.replace(/\n{2,}/g, '\n');

                const dmFieldKeys = ['主线', '支线与约定', '暗线', '个人线', '下轮注意'];
                const dmFieldStartRegex = /[（\(]\s*(主线|支线与约定|暗线|个人线|下轮注意)\s*[:：]/g;
                const dmFieldBlocks = (() => {
                    const blocks = {};
                    const matches = [...cleanDm.matchAll(dmFieldStartRegex)];
                    for (let i = 0; i < matches.length; i++) {
                        const match = matches[i];
                        const key = match[1];
                        const start = match.index + match[0].length;
                        const end = i + 1 < matches.length ? matches[i + 1].index : cleanDm.length;
                        let value = cleanDm.slice(start, end).trim();
                        if (value.endsWith('）') || value.endsWith(')')) value = value.slice(0, -1).trimEnd();
                        blocks[key] = value;
                    }
                    return blocks;
                })();

                const getDmField = (key) => dmFieldKeys.includes(key) ? (dmFieldBlocks[key] || '') : '';

                const darkLine = getDmField('暗线');
                const nextNote = getDmField('下轮注意');

                const mainLineRaw = getDmField('主线');
                let mainLineHTML = '';
                if ((mainLineRaw && mainLineRaw !== '无') || (darkLine && darkLine !== '无') || (nextNote && nextNote !== '无')) {
                    let mainLineItems = [];
                    if (mainLineRaw && mainLineRaw !== '无') {
                        // 尝试解析子字段: 进展/走向/铺垫
                        const subRegex = new RegExp(`(?:^|\\n)\\s*[·・•\\-\\*\+]?\\s*(进展|走向|铺垫)\\s*[:：\\-\\s]+([\\s\\S]*?)(?=(?:\\n\\s*[·・•\\-\\*\+]?\\s*(?:进展|走向|铺垫)\\s*[:：])|$)`, 'gi');
                        let hasSubs = false;
                        let m;
                        while ((m = subRegex.exec(mainLineRaw)) !== null) {
                            hasSubs = true;
                            mainLineItems.push({ name: m[1].trim(), text: m[2].trim() });
                        }
                        if (!hasSubs) {
                            mainLineItems.push({ name: '进展', text: mainLineRaw });
                        }
                    }
                    if (darkLine && darkLine !== '无') {
                        mainLineItems.push({ name: '暗线', text: darkLine });
                    }
                    if (nextNote && nextNote !== '无') {
                        mainLineItems.push({ name: '注意', text: nextNote });
                    }

                    if (mainLineItems.length > 0) {
                        mainLineHTML = `<div class="npc-group" style="margin-bottom:12px;">
                            <div class="npc-group-label" style="margin-bottom:8px;">主线</div>
                            <div style="display:flex; flex-direction:column;">` +
                            mainLineItems.map(item => {
                                let labelStyle = item.name === '注意' ? 'color:var(--theme-color-1);' : '';
                                return `<div class="npc-row"><span class="npc-row-label" style="${labelStyle}">${item.name}</span><span class="npc-row-val">${item.text}</span></div>`;
                            }).join('') +
                            `</div></div>`;
                    }
                }

                const personalContent = getDmField('个人线');
                let personalLines = [];
                if (personalContent) {
                    personalLines = personalContent.split('\n').map(l => {
                        let trimmed = l.trim();
                        if (!trimmed || trimmed === '无' || trimmed === '）' || trimmed === ')') return null;
                        if (trimmed.endsWith('）') || trimmed.endsWith(')')) trimmed = trimmed.slice(0, -1).trimEnd();

                        let m = trimmed.match(/^[·・•\-\*\+]\s*(.+?)\s*[—\-–~～:：]+\s*(.*)$/);
                        if (m) return { name: m[1].trim(), progress: m[2].trim() };
                        m = trimmed.match(/^([^\s·・•\-\*\+][^—\-–~～:：]{0,14})\s*[—\-–~～:：]+\s*(.*)$/);
                        if (m) return { name: m[1].trim(), progress: m[2].trim() };
                        m = trimmed.match(/^[·・•\-\*\+]\s*([^\s]{1,15})\s+(.*)$/);
                        if (m) return { name: m[1].trim(), progress: m[2].trim() };
                        if (/^[·・•\-\*\+]/.test(trimmed)) return { name: "✧", progress: trimmed.replace(/^[·・•\-\*\+]\s*/, '') };
                        if (trimmed.length > 2) return { name: "✧", progress: trimmed };
                        return null;
                    }).filter(x => x && x.progress);
                }

                // 新增：支线与约定 解析
                const sideAndPromisesRaw = getDmField('支线与约定');
                let sideHTML = '', promisesHTML = '', enemiesHTML = '';
                if (sideAndPromisesRaw) {
                    const extractBlock = (title) => {
                        const regex = new RegExp(`\\[${title}\\]([\\s\\S]*?)(?=\\n\\s*\\[|$)`, 'i');
                        const m = sideAndPromisesRaw.match(regex);
                        return m ? m[1].trim() : '';
                    };

                    const cluesText = extractBlock('支线');
                    const promisesText = extractBlock('约定');
                    const enemiesText = extractBlock('敌方');

                    if (cluesText && cluesText !== '无') {
                        const clueItems = cluesText.split('\n').map(l => l.trim()).filter(l => /^[·・•\-\*\+]/.test(l)).map(l => {
                            const lm = l.match(/^[·・•\-\*\+]\s*(?:\[(主线|支线|个人线|[^\]]+)\])?\s*([^→|]+?)(?:\s*→\s*([^|]+?))?(?:\s*[|｜]\s*谁在意\s*[=＝]\s*(.*))?$/);
                            if (!lm) return null;
                            const text = lm[2].trim();
                            if (text === '无' || text === '') return null;
                            let status = lm[3] ? lm[3].trim() : '';
                            status = status.replace(/^状态\s*\{?|\}?$/g, '').trim();
                            return { weight: lm[1] ? lm[1].trim() : '', text, status, who: lm[4] ? lm[4].trim() : '' };
                        }).filter(x => x);

                        if (clueItems.length > 0) {
                            sideHTML += `<div class="npc-group" style="margin-bottom:12px;"><div class="npc-group-label" style="margin-bottom:8px;">支线</div><div class="objectives-list">` +
                                clueItems.map(o => {
                                    const isShelved = /搁置|shelved|suspended/i.test(o.status);
                                    const stateClass = isShelved ? 'obj-pending' : 'obj-active';
                                    const stateIcon = isShelved ? '✧' : '◈';
                                    const wTags = o.weight ? `<span class="obj-weight" data-weight="${o.weight}">${o.weight}</span>` : '';
                                    const statusText = o.status ? `<span class="obj-condition">▸ ${o.status}</span>` : '';
                                    let whoHTML = '';
                                    if (o.who) {
                                        let whoClean = o.who.replace(/^\{|^\s*|^\s*\[|\}\s*$|\]\s*$/g, '').trim();
                                        if (whoClean && whoClean !== '无' && whoClean !== '-') {
                                            const itemsHTML = Array.from(whoClean.matchAll(/([^(（,，]+)(?:[（(](.*?)[）)])?/g)).map(m => {
                                                const name = m[1].trim();
                                                if (!name) return '';
                                                return `<span style="color:var(--theme-color-1); font-size:calc(var(--base-font-size) - 2px);">[${name}]</span>${m[2] ? `<span style="color:var(--text-sub); font-size:calc(var(--base-font-size) - 2px); margin-left:2px; margin-right:4px;">${m[2].trim()}</span>` : ''}`;
                                            }).join('');
                                            whoHTML = `<span class="obj-condition" style="margin-left:4px; margin-right:2px;">▸</span>${itemsHTML}`;
                                        }
                                    }
                                    return `<div class="obj-item ${stateClass}"><span class="obj-icon">${stateIcon}</span><div class="obj-content" style="flex-direction:row;align-items:baseline;flex-wrap:wrap;gap:2px">${wTags}<span class="obj-text">${o.text}</span>${statusText}${whoHTML}</div></div>`;
                                }).join('') + `</div></div>`;
                        }
                    }

                    if (promisesText && promisesText !== '无') {
                        const promises = promisesText.split('\n').map(l => l.trim()).filter(l => /^[·・•\-\*\+]/.test(l)).map(l => {
                            const m = l.match(/^[·・•\-\*\+]\s*(.+?)[:：](?!\d)\s*(.*)/);
                            if (m) {
                                const who = m[1].trim();
                                const content = m[2].trim();
                                if ((who === '无/无' || who === '无') && (content === '无' || content === '')) return null;
                                return { who, content };
                            }
                            return null;
                        }).filter(x => x);

                        if (promises.length > 0) {
                            promisesHTML = `<div class="npc-group" style="margin-bottom:12px;"><div class="npc-group-label" style="margin-bottom:8px;">未了之约</div><div class="promise-list">` +
                                promises.map(p => `<div class="promise-item"><span style="color:var(--theme-color-1);font-size:calc(var(--base-font-size) - 1px);margin-right:4px;">[${p.who}]</span><span class="promise-content">${p.content}</span></div>`).join('') +
                                `</div></div>`;
                        }
                    }

                    if (enemiesText && enemiesText !== '无') {
                        const hourglassSVG = `<svg xmlns="http://www.w3.org/2000/svg" width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="vertical-align:-1.5px;opacity:0.7;margin:0 2px;"><path d="M5 22h14"/><path d="M5 2h14"/><path d="M17 22v-4.172a2 2 0 0 0-.586-1.414L12 12l-4.414 4.414A2 2 0 0 0 7 17.828V22"/><path d="M7 2v4.172a2 2 0 0 0 .586 1.414L12 12l4.414-4.414A2 2 0 0 0 17 6.172V2"/></svg>`;
                        const enemies = enemiesText.split('\n').map(l => l.trim()).filter(l => /^[·・•\-\*\+]/.test(l)).map(l => {
                            const parts = l.replace(/^[·・•\-\*\+]\s*/, '').split(/[|｜]/);
                            const mainPart = parts[0].trim();
                            const timePart = parts[1] ? parts[1].trim() : '';
                            const m = mainPart.match(/(.*?)[:：]\s*(.*)/);
                            return { name: m ? m[1].trim() : mainPart, action: m ? m[2].trim() : '', time: timePart.replace(/预计行动时间[:：]?\s*/i, '').trim() };
                        });

                        if (enemies.length > 0 && enemies[0].name !== '无') {
                            enemiesHTML = `<div class="npc-group" style="margin-bottom:12px;"><div class="npc-group-label" style="margin-bottom:8px;">暗流涌动</div><div style="display:flex; flex-direction:column; gap:6px;">` +
                                enemies.map(e => `<div style="display:flex;flex-wrap:wrap;align-items:baseline;gap:4px;font-size:calc(var(--base-font-size) - 1px);line-height:1.6;color:var(--text-main);"><span style="color:var(--theme-color-1);flex-shrink:0;">[${e.name}]</span><span>${e.action}</span>${e.time ? `<span style="color:var(--text-weak);font-size:calc(var(--base-font-size) - 3px);display:inline-flex;align-items:baseline;gap:2px;flex-shrink:0;">${hourglassSVG}${e.time}</span>` : ''}</div>`).join('') +
                                `</div></div>`;
                        }
                    }
                }

                let evalRowsHTML = '';

                let dmItemsHTML = '';
                if (mainLineHTML) dmItemsHTML += mainLineHTML;
                if (evalRowsHTML) dmItemsHTML += `<div class="entry-eval-box" style="margin-bottom:12px;">${evalRowsHTML}</div>`;

                dmItemsHTML += sideHTML + promisesHTML + enemiesHTML;

                if (personalLines.length > 0) {
                    dmItemsHTML += `<div class="npc-group" style="margin-bottom:12px;">
                        <div class="npc-group-label" style="margin-bottom:8px;">个人线</div>
                        <div style="display:flex; flex-direction:column; gap:6px;">` +
                        personalLines.map(p => `<div><span style="color:var(--theme-color-1); font-weight:bold; margin-right:8px; font-size:calc(var(--base-font-size) - 3px);">${p.name}</span><span style="color:var(--text-main); line-height:1.5; font-size:calc(var(--base-font-size) - 2px);">${p.progress}</span></div>`).join('') +
                        `</div></div>`;
                }

                // 如果都没有匹配到任何预定义结构，则降级兼容原版内容（避免内容全空）
                if (!dmItemsHTML && cleanDm && cleanDm !== 'Edward:' && cleanDm !== 'Edward：') {
                    const fallbackText = cleanDm.replace(/^Edward[:：]?/i, '').trim();
                    if (fallbackText) {
                        dmItemsHTML += `<div class="entry-eval-box"><div class="entry-eval-row"><span class="entry-eval-val" style="white-space:pre-wrap;">${fallbackText}</span></div></div>`;
                    }
                }

                if (dmItemsHTML) {
                    dmBoxHTML = `<div class="section"><div class="sec-header" onclick="toggleSection(this)"><span class="sec-title">旋律手稿</span><span class="sec-arrow">✧</span></div><div class="sec-content" style="padding-top:12px;">${dmItemsHTML}</div></div>`;
                }
            }

            const npcOpen = Config.data.collapseNpc ? '' : 'open';

            let yongtanSectionHTML = '';
            if (npcSectionHTML.trim()) {
                yongtanSectionHTML = `<div class="section ${npcOpen}"><div class="sec-header" onclick="toggleSection(this)"><span class="sec-title">咏叹心声</span><span class="sec-arrow">✧</span></div><div class="sec-content">${npcSectionHTML}</div></div>`;
            }

            const finalHTML =
                `<div class="section"><div class="sec-header" onclick="toggleSection(this)"><span class="sec-title">光阴折痕</span><span class="plot-count">${plots.length} Plot</span><span class="sec-arrow">✧</span></div><div class="sec-content"><div class="plot-tags">${plots.length > 0 ? plots.map(p => `<span class="plot-tag" onclick="togglePlotMemory('${p}','plot-reader')">${p}</span>`).join('') : '<div style="font-size:12px;color:var(--text-sub);text-align:center">✦ 无召回记录</div>'}</div><div class="plot-reader-panel" id="plot-reader"></div></div></div>` +
                chapterStatusHTML +
                yongtanSectionHTML +
                offstageHTML + overtonesHTML + dmBoxHTML + fileContentHTML;

            document.getElementById('render-area').innerHTML = finalHTML;
        }


        setTimeout(() => { Config.load(); render(); }, 100);
    </script>
</body>

</html>
```
